 const C=ConnectedCore,R=C.rules,q=R.q,by=id=>document.getElementById(id),copy=structuredClone,esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
