function durationExact(raw){const value=num(raw),hours=Math.floor(value/3600),minutes=Math.floor((value-hours*3600)/60),seconds=ConnectedCore.offset(raw,String(hours*3600+minutes*60));return (hours?hours+'小时':'')+(minutes?minutes+'分':'')+(num(seconds)?seconds+'秒':'')||'0秒';}
function dayClock(raw){const seconds=num(raw),day=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60),s=ConnectedCore.offset(raw,String(day*86400+h*3600+m*60));return '第'+(day+1)+'天 '+h+':'+String(m).padStart(2,'0')+(num(s)?':'+(num(s)<10?'0':'')+s:'');}
function showConflict(record){
 const c=record.conflict;if(!c)return;const g=record.game,{v,behavior}=ConnectedCore.compile(g),slots=ConnectedCore.schedule(behavior,v.simulation.observationSeconds),index=slots.findIndex((s,i)=>slots[i+1]&&Math.abs(num(s.end.toString())+num(g.rules.battleTimeoutSeconds)-c.from)<1e-6&&Math.abs(num(slots[i+1].start.toString())-c.to)<1e-6);if(index<0)return;
 const slot=slots[index],next=slots[index+1].start.toString(),end=slot.end.toString(),lastBattle=ConnectedCore.offset(end,ConnectedCore.scaled(g.rules.battleTimeoutSeconds,'-1')),gap=ConnectedCore.offset(next,lastBattle);
 const shortClock=raw=>Math.floor(num(raw)/86400)===Math.floor(num(slot.start.toString())/86400)?dayClock(raw).split(' ')[1]:dayClock(raw);
 by('cgConflictTiming').textContent=dayClock(slot.start.toString())+'上线，'+shortClock(end)+'下线，下一次要到'+shortClock(next)+'才回来。下线后不继续挑战新关。';
 by('cgConflictReason').textContent='即使预留正在打的那场战斗，仍至少有'+durationExact(gap)+'没有新关，超过你设的'+durationExact(g.goals.maxGapSeconds)+'。你还要求至少'+durationExact(g.goals.minCompletionSeconds)+'才打完，无法在这段空档开始前结束全部关卡。';
 by('cgConflictEvidence').textContent='下线时刻 '+dayClock(end)+'；已开始的战斗最多再结算'+durationExact(g.rules.battleTimeoutSeconds)+'。因此从'+dayClock(lastBattle)+'到'+dayClock(next)+'，没有新关的精确下界为'+durationExact(gap)+'（'+gap+'秒）。最长未推进时间目标为'+durationExact(g.goals.maxGapSeconds)+'。';
 conflictBox.hidden=false;
}
