function presentBattle(){
 const battle=replay?.executed.battle;if(battle?.time!==undefined)by('cgBattleTitle').textContent+=' · '+time(battle.time);
 battleFacts.innerHTML='<h4>伤害与恢复</h4>'+(replay?.executed.metrics||[]).map((m,i)=>{const parts=[];if(m.actualDamage!==undefined)parts.push('造成伤害'+f(m.actualDamage));if(num(m.leechApplied)>0)parts.push('实际吸血'+f(m.leechApplied));if(num(m.regenApplied)>0)parts.push('实际回复'+f(m.regenApplied));return parts.length?'<p>'+(i?'敌人':'角色')+'：'+escape(parts.join('，'))+'。</p>':'';}).join('');
 by('cgPlayBattle').disabled=!replay?.executed.steps.length;
 const inputGame=selectedRun?.inputGame;ruleEventsPanel.hidden=!ConnectedCore.rules.config(inputGame);by('cgRuleBattleMeaning').textContent=inputGame?ConnectedCore.rules.describe(inputGame):'';
 const eventNames={damage:'扣血',state_applied:'施加状态',state_expired:'状态到期',action_blocked:'行动被禁止',reaction:'状态反应',trigger:'条件触发',shield_gain:'获得护盾',heal:'固定回复',module:'扩展模块',module_heal:'模块回复'};by('cgRuleEventRows').innerHTML=(replay?.executed.steps||[]).flatMap(s=>s.events||[]).slice(0,100).map(e=>{const info=ConnectedRules.eventInfo(inputGame,e),link=info.ref?'<button type="button" class="cg-rule-edit" data-edit-rule="'+escape(info.ref.kind+':'+info.ref.id)+'">查看并修改这个效果</button>':'';return '<tr><td>'+time(e.time)+'</td><td>'+escape(eventNames[e.kind]||e.kind)+'</td><td>'+(e.kind==='damage'?(e.side===0?'角色':'敌人')+' → '+(e.target===0?'角色':'敌人'):(e.side===0?'角色':e.side===1?'敌人':''))+'</td><td>'+escape(info.text)+link+'</td></tr>';}).join('');
}
