function openDetail(node,title,trigger=document.activeElement){const previous=detailStack.at(-1);if(previous){previous.contentTop=by('cgDetailContent').scrollTop;previous.node.hidden=true;}const anchor=document.createComment('detail home');node.before(anchor);detailStack.push({node,title,trigger,anchor,top:window.scrollY,contentTop:0});node.hidden=false;node.classList.add('cg-panel-active');if(node.tagName==='DETAILS')node.open=true;by('cgDetailContent').append(node);by('cgDetailTitle').textContent=title;by('cgDetailBack').textContent=detailStack.length>1?'返回'+previous.title:'返回检查结果';if(!detailDialog.open)detailDialog.showModal();by('cgDetailContent').scrollTop=0;by('cgDetailBack').focus();panelRefresh();}
function closeDetail(){const state=detailStack.pop();if(!state)return;state.node.classList.remove('cg-panel-active');if(state.node.id==='cgBattle'){stopPlayback();state.node.hidden=true;}else state.node.hidden=false;state.anchor.replaceWith(state.node);const previous=detailStack.at(-1);if(previous){previous.node.hidden=false;by('cgDetailTitle').textContent=previous.title;by('cgDetailBack').textContent=detailStack.length>1?'返回'+detailStack[detailStack.length-2].title:'返回检查结果';by('cgDetailContent').scrollTop=previous.contentTop;}else{detailDialog.close();window.scrollTo({top:state.top,behavior:'instant'});}state.trigger?.focus?.({preventScroll:true});panelRefresh();}
