function projectDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('idle-workshop-projects',1);req.onupgradeneeded=()=>{req.result.createObjectStore('projects',{keyPath:'id'});req.result.createObjectStore('meta');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
