const projectBeforeProjects=project;project=function(includeResults=false){return {...projectBeforeProjects(includeResults),projectMeta:copy({...projectMeta,id:activeProjectId,version:studioVersion}),...(dirty&&formReady?{formDraft:formDraft()}:{} )};};
const loadBeforeProjects=loadProject;loadProject=function(data){if(projectSwitching)return loadBeforeProjects(data);const checkpoint=projectRecord();if(data?.format==='idle-workshop-project-1'&&!data.content&&!data.draft)throw Error('项目文件里没有数据或草稿');projectSwitching=true;try{if(data?.format==='idle-workshop-project-1'){if(data.content)loadBeforeProjects(data.content);else resetWorkspace();restoreFormDraft(data.draft);projectMeta=copy(data.meta||{});if(data.draft)show('data');}else{loadBeforeProjects(data);projectMeta=copy(data.projectMeta||{});if(data.formDraft){restoreFormDraft(data.formDraft);show('data');}}if(checkpoint)saveProjectRecord(checkpoint).catch(()=>{});activeProjectId=crypto.randomUUID();projectMeta={...projectMeta,id:activeProjectId,version:studioVersion};projectIds.add(activeProjectId);}catch(error){if(checkpoint){resetWorkspace();activeProjectId=checkpoint.id;projectMeta=copy(checkpoint.meta);if(checkpoint.content)loadBeforeProjects(checkpoint.content);restoreFormDraft(checkpoint.draft);show(checkpoint.draft?.dirty?'data':checkpoint.view);}throw error;}finally{projectSwitching=false;}scheduleProjectSave();};
