let tableIntake=null;
const tableView=make('section','cgTableIntake','<h2>把表格对应到游戏数据</h2><p id="cgTableState" role="status"></p><div id="cgTableControls" class="fields"></div><details id="cgTableSource"><summary>查看原表</summary><div class="cg-table-scroll" tabindex="0" id="cgTableRaw"></div></details><p>已识别的对应可直接填入；只有下方列出的歧义需要处理。没有对应的项目会随项目保留，不参与计算。窄屏可左右滑动表格。</p><div class="cg-intake-pager"><span id="cgIntakePageState"></span><button type="button" id="cgIntakePrev">上一组</button><button type="button" id="cgIntakeNext">下一组</button></div><div class="cg-table-scroll" tabindex="0" aria-label="字段对应表"><table class="cg-intake-table"><thead><tr><th>原表字段与数值</th><th>填到哪里</th><th>原表单位</th><th>换算结果</th></tr></thead><tbody id="cgTableRows"></tbody></table></div><p id="cgTableMeaning"></p><p id="cgTableError" class="form-error" role="alert" hidden></p><div class="actions" id="cgIntakeActions"><button type="button" id="cgCancelTable">取消导入</button><button type="button" class="primary" id="cgApplyTable">填入已识别数据</button></div>');tableView.hidden=true;by('cgEmpty').after(tableView);
