const tableUnitOptions={number:[['number','按原数值']],count:[['number','整数']],percent:[['','请确认百分比写法'],['percent','20 表示20%'],['ratio','0.2 表示20%']],frequency:[['','请确认攻速单位'],['perSecond','每秒攻击次数'],['intervalSeconds','每次间隔，秒'],['intervalMs','每次间隔，毫秒'],['perMinute','每分钟攻击次数']],seconds:[['','请选择原表单位'],['seconds','秒'],['milliseconds','毫秒'],['minutes','分钟'],['hours','小时']],minutes:[['','请选择原表单位'],['seconds','秒'],['minutes','分钟'],['hours','小时']],hours:[['','请选择原表单位'],['seconds','秒'],['minutes','分钟'],['hours','小时']]};
function intakeBase(){if(formReady&&by('cgV2Editor')){const draft=ConnectedV2.draft(),merge=copy(game||ConnectedV2.blank());for(const key of ['types','mechanisms','player','upgrades','strategy','ruleLibrary','rules','economy','ruleScope'])if(draft[key]!==undefined)merge[key]=copy(draft[key]);merge.world={...merge.world,...copy(draft.world)};return merge;}return ConnectedV2.is(game)?copy(game):ConnectedV2.blank();}
function intakeMessage(message,error=false){by('cgTableError').hidden=!error;by('cgTableError').textContent=error?message:'';if(!error)by('cgTableState').textContent=message;}
function chooseIntakeSheet(index){const s=tableIntake;s.sheet=Number(index);s.page=0;s.items=ConnectedIntake.entries([s.source.sheets[s.sheet]]);s.mappings=s.items.map(item=>{const suggestion=ConnectedIntake.suggest(item,s.targets,projectMeta.intake?.mapping||{}),target=s.targets.find(t=>t.id===suggestion.target);if(suggestion.valueOverride!==undefined){if(String(item.value)===String(suggestion.originalValue))item.value=suggestion.valueOverride;else{delete suggestion.valueOverride;delete suggestion.originalValue;}}return {...suggestion,unit:suggestion.unitChanged?'':suggestion.unit||ConnectedIntake.inferUnit(item,target)};});renderIntake();}
function targetOptions(selected){const groups=new Map();for(const t of tableIntake.targets){const group=t.label.split(' / ')[0];if(!groups.has(group))groups.set(group,[]);groups.get(group).push(t);}return '<option value="">保留原值，不参与计算</option>'+[...groups].map(([name,rows])=>'<optgroup label="'+escape(name)+'">'+rows.map(t=>'<option value="'+escape(t.id)+'"'+(t.id===selected?' selected':'')+'>'+escape(t.label)+'</option>').join('')+'</optgroup>').join('');}
function renderIntake(){const s=tableIntake;if(!s)return;by('cgTableControls').innerHTML='<label>选择工作表<select id="cgIntakeSheet">'+s.source.sheets.map((sheet,i)=>'<option value="'+i+'"'+(s.sheet===i?' selected':'')+'>'+escape(sheet.name)+'</option>').join('')+'</select></label><label>本次导入到<select id="cgIntakeDestination"><option value="current"'+(s.destination==='current'?' selected':'')+'>当前项目（只更新已对应字段）</option><option value="new"'+(s.destination==='new'?' selected':'')+'>新项目，保留当前项目</option></select></label>';
 by('cgTableRows').innerHTML=s.items.slice(s.page*20,(s.page+1)*20).map((item,index)=>{const i=s.page*20+index,m=s.mappings[i],target=s.targets.find(t=>t.id===m.target),options=tableUnitOptions[target?.kind||'number'];return '<tr><td><strong>'+escape((item.owner?item.owner+' / ':'')+item.name)+'</strong><label><span class="cg-sr-only">第'+(i+1)+'项本次使用数值</span><input id="cg-import-value-'+i+'" data-source-value="'+i+'" value="'+escape(item.value)+'"></label><small>原表单位：'+escape(item.unit||'未注明')+'</small><small>'+escape(item.source)+(m.reused?' · 复用项目对应':'')+(m.ambiguous?' · 名称有歧义，请选择':'')+'</small></td><td><label><span class="cg-sr-only">第'+(i+1)+'项填到哪里</span><select id="cg-import-map-'+i+'" data-map="'+i+'">'+targetOptions(m.target)+'</select></label></td><td><label><span class="cg-sr-only">第'+(i+1)+'项原表单位</span><select id="cg-import-unit-'+i+'" data-unit="'+i+'"'+(!target?' disabled':'')+'>'+options.map(([value,label])=>'<option value="'+value+'"'+(m.unit===value?' selected':'')+'>'+label+'</option>').join('')+'</select></label></td><td data-converted="'+i+'"></td></tr>';}).join('');by('cgIntakePageState').textContent='第'+(s.page*20+1)+'–'+Math.min((s.page+1)*20,s.items.length)+'项，共'+s.items.length+'项';by('cgIntakePrev').disabled=s.page===0;by('cgIntakeNext').disabled=(s.page+1)*20>=s.items.length;
 const sheet=s.source.sheets[s.sheet];by('cgTableRaw').innerHTML='<table><tbody>'+sheet.rows.slice(0,12).map((row,i)=>'<tr>'+row.slice(0,12).map(value=>'<'+(i?'td':'th')+'>'+escape(typeof value==='object'?JSON.stringify(value):value)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table><p>预览前12行、12列；原表共'+sheet.rows.length+'行，全部数据随项目保存。</p>';
 by('cgIntakeDestination').disabled=!activeProjectId;s.destination=activeProjectId?s.destination:'new';by('cgIntakeDestination').value=s.destination;refreshIntakeValues();
}
function refreshIntakeValues(){const s=tableIntake;if(!s)return;const issues=ConnectedIntake.inspect(s.targets,s.mappings,s.items);s.issues=issues;
 let matched=0;for(let i=0;i<s.items.length;i++){const m=s.mappings[i],target=s.targets.find(t=>t.id===m.target),cell=by('cgTableRows').querySelector('[data-converted="'+i+'"]'),issue=issues.find(x=>x.index===i);if(target&&!issue)matched++;if(cell){cell.textContent=issue?issue.message:ConnectedIntake.convert(s.items[i],target,m.unit).text;cell.classList.toggle('cg-intake-error',!!issue);}for(const control of by('cgTableRows').querySelectorAll('[data-map="'+i+'"],[data-unit="'+i+'"],[data-source-value="'+i+'"]')){control.removeAttribute('aria-invalid');if(issue&&control.id===intakeIssueField(issue))control.setAttribute('aria-invalid','true');}}
 const unitChanges=s.mappings.filter(m=>m.unitChanged&&!m.unit).length;by('cgTableState').textContent=s.source.name+'：'+matched+'项对应明确，'+issues.length+'项待处理，'+s.mappings.filter(m=>!m.target&&!m.ambiguous).length+'项保留原值。'+(unitChanges?' '+unitChanges+'项原表单位已变，请重新确认。':'');by('cgApplyTable').disabled=!!issues.length||!matched;applyBattleTable.hidden=!issues.length;applyBattleTable.disabled=!matched||issues.some(x=>x.affects==='combat');
 intakeIssues.hidden=!issues.length;intakeIssues.innerHTML=issues.length?'<h3>只需处理这'+issues.length+'项</h3>'+issues.map(issue=>{const item=s.items[issue.index],mapping=s.mappings[issue.index],candidates=(mapping.candidates||[]).map(id=>s.targets.find(t=>t.id===id)?.label).filter(Boolean);return '<p>'+escape(item.source+' · '+(item.owner?item.owner+' / ':'')+item.name)+'：'+escape(issue.message)+'（影响'+(issue.affects==='combat'?'单场战斗':'长期检查')+'）'+(mapping.ambiguous&&candidates.length?'<br>候选：'+escape(candidates.join('；')):'')+' <button type="button" data-intake-fix="'+issue.index+'">前往修改第'+(issue.index+1)+'项</button></p>';}).join(''):'';
 by('cgTableMeaning').textContent=issues.length?(issues.some(x=>x.affects==='combat')?'有未解决的战斗字段或单位，处理后才能计算本场。':'剩余问题只影响长期检查；可先填入明确数据计算单场，再回来补齐。'):'已识别的字段和单位无需逐项重复确认，可直接填入；也可在表中修改对应。';
}
function intakeIssueField(issue){const m=tableIntake.mappings[issue.index];return 'cg-import-'+(!m?.target||/多笔|对应已经变化/.test(issue.message)?'map':/单位|写法/.test(issue.message)?'unit':'value')+'-'+issue.index;}
function focusIntakeIssue(index){const issue=tableIntake?.issues?.find(x=>x.index===index);if(!issue)return;tableIntake.page=Math.floor(index/20);renderIntake();const el=by(intakeIssueField(issue));el?.closest('tr').classList.add('cg-field-target');el?.scrollIntoView({block:'center',inline:'center',behavior:'instant'});el?.focus({preventScroll:true});}
intakeIssues.onclick=e=>{const button=e.target.closest('[data-intake-fix]');if(button)focusIntakeIssue(Number(button.dataset.intakeFix));};

tableView.addEventListener('change',e=>{const s=tableIntake;if(!s)return;if(e.target.id==='cgIntakeSheet'){chooseIntakeSheet(e.target.value);return;}if(e.target.id==='cgIntakeDestination'){s.destination=e.target.value;s.base=s.destination==='new'?ConnectedV2.blank():intakeBase();s.targets=ConnectedIntake.targets(s.base);chooseIntakeSheet(s.sheet);return;}if(e.target.dataset.map!==undefined){const i=Number(e.target.dataset.map),target=s.targets.find(t=>t.id===e.target.value);s.mappings[i]={...s.mappings[i],target:e.target.value,unit:ConnectedIntake.inferUnit(s.items[i],target),reused:false,ambiguous:false,resolved:true};renderIntake();by('cgTableRows').querySelector('[data-map="'+i+'"]').focus({preventScroll:true});}else if(e.target.dataset.unit!==undefined){s.mappings[Number(e.target.dataset.unit)].unit=e.target.value;refreshIntakeValues();}});
tableView.addEventListener('input',e=>{if(e.target.dataset.sourceValue===undefined||!tableIntake)return;const i=Number(e.target.dataset.sourceValue);if(tableIntake.mappings[i].originalValue===undefined)tableIntake.mappings[i].originalValue=tableIntake.items[i].value;tableIntake.items[i].value=e.target.value;tableIntake.mappings[i].valueOverride=e.target.value;refreshIntakeValues();});
const showBeforeTable=show;show=function(view,options){showBeforeTable(view==='import'?'none':view,options);if(view==='import'){workspaceView='import';actionBar.hidden=false;by('cgPrimary').hidden=true;by('cgSecondary').hidden=true;actionBar.append(by('cgIntakeActions'));by('cgActionState').textContent='确认对应后才更新项目，取消会保留当前数据。';}else{by('cgPrimary').hidden=false;tableView.append(by('cgIntakeActions'));}tableView.hidden=view!=='import';};
const chromeBeforeTable=updateChrome;updateChrome=function(){chromeBeforeTable();if(workspaceView==='import'&&tableIntake){actionBar.hidden=false;by('cgPrimary').hidden=true;by('cgSecondary').hidden=true;by('cgActionState').textContent='确认对应后才更新项目，取消会保留当前数据。';}};
by('cgIntakePrev').onclick=()=>{if(tableIntake.page>0){tableIntake.page--;renderIntake();}};by('cgIntakeNext').onclick=()=>{if((tableIntake.page+1)*20<tableIntake.items.length){tableIntake.page++;renderIntake();}};
