async function openTableFile(file){const isJSON=/\.json$/i.test(file.name);if(file.size>(isJSON?256:15)*1024*1024)throw Error(isJSON?'文件超过256MB，请减少一次导出的记录':'表格超过15MB，请缩小表格后导入');let sheets;if(isJSON){let data;try{data=JSON.parse(await file.text());}catch{throw Error('JSON格式有误，请检查逗号与括号；当前项目未改动');}if(['idle-connected-game-v1','idle-connected-game-v2','idle-connected-workbench-results-v1','idle-connected-workbench-project-v1','multi-battle-v1','idle-workshop-project-1'].includes(data?.format)){loadProject(data);return;}sheets=ConnectedIntake.fromJSON(data);}else{if(typeof XLSX==='undefined')throw Error('表格读取组件未载入，请刷新页面再试');const bytes=await file.arrayBuffer();let raw;if(/\.(csv|tsv)$/i.test(file.name)){try{raw=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{raw=new TextDecoder('gb18030').decode(bytes);}}const book=XLSX.read(raw??bytes,{type:raw!==undefined?'string':'array',raw:true,cellNF:true,cellFormula:true});sheets=ConnectedIntake.readBook(book,XLSX);}
 const legacy=game&&!ConnectedV2.is(game),base=legacy?ConnectedV2.blank():intakeBase();tableIntake={source:{version:ConnectedIntake.VERSION,name:file.name,size:file.size,importedAt:new Date().toISOString(),sheets},base,targets:ConnectedIntake.targets(base),previous:workspaceView,destination:activeProjectId&&!legacy?'current':'new',sheet:0,items:[],mappings:[]};chooseIntakeSheet(0);if(legacy)by('cgIntakeDestination').querySelector('option[value=current]').disabled=true;show('import');window.scrollTo({top:0,behavior:'instant'});
}
