const scheduleNotice=make('section','cgScheduleNotice','<h3>目标与上线安排有冲突</h3><p id="cgScheduleMeaning"></p><div class="actions"><button type="button" id="cgScheduleEdit">修改上线安排或目标</button><button type="button" id="cgScheduleRun">仍检查实际节奏</button></div>');scheduleNotice.hidden=true;scheduleNotice.className='cg-schedule-notice';by('cgGoals').after(scheduleNotice);
