function checkDraftSchedule(){if(!formReady||by('cgGoalMode').value!=='set')return scheduleNotice.hidden=true;try{const g=ConnectedV2.draft();g.name=by('cgName').value;g.behavior={...g.behavior,mode:by('cg-behavior').value,visitHours:by('cg-hours').value.split(',').map(Number),sessionMinutes:by('cg-session').value};g.simulation={...g.simulation,observationSeconds:ConnectedCore.scaled(by('cg-budget').value,'3600')};g.goals={...g.goals,minCompletionSeconds:by('cgGoalMin').value?ConnectedCore.scaled(by('cgGoalMin').value,String(units[by('cgGoalUnit').value])):null,maxGapSeconds:by('cgGoalGap').value?ConnectedCore.scaled(by('cgGoalGap').value,String(units[by('cgWaitUnit').value])):null};showScheduleConflict(g);}catch{scheduleNotice.hidden=true;}}
by('cgScheduleEdit').onclick=()=>openSetting('cg-hours');by('cgScheduleRun').onclick=()=>{checkedConflict=fingerprint(game);simulate(pendingConflictRun);};
