function battleConclusion(input,result){
 if(result.battle.outcome==='interrupted_budget')return '<p>已恢复旧版单击算例；整场战斗尚未计算，点击计算查看能否通过。</p>';
 const b=result.battle,meaning=b.outcome==='win'?'能过这场战斗':b.outcome==='death'?'这场会先死亡':b.outcome==='draw'?'双方同归于尽，未通过':'限时内打不赢',reason=b.outcome==='win'?'击倒敌人时，角色剩余'+f(b.playerHp)+'点生命。':b.outcome==='death'?'角色生命先降到0，敌人仍剩'+f(b.enemyHp)+'点生命。':b.outcome==='draw'?'双方在同一时刻生命降到0。':'到'+time(input.rules.timeoutSeconds)+'战斗时限，敌人仍剩'+f(b.enemyHp)+'点生命；本次输出未能在限时内击倒敌人。';
 return '<section class="cg-single-result" aria-label="单场战斗结果"><h4>'+meaning+'</h4><p>'+escape(reason)+'</p><p>战斗耗时 <strong>'+time(b.time)+'</strong>；角色 / 敌人剩余生命 '+f(b.playerHp)+' / '+f(b.enemyHp)+'点。</p><p class="cg-single-scope">本次计算：当前双方属性的一场战斗，编号'+input.seed+'。攒钱、升级、计划离线、换关间隔和总周期尚未计算。</p></section>';
}
